export const PLAY_ID_PREFIX="custom-",PATH_PLAYERS=Object.freeze(["wr1","wr2","wr3","wr4","qb"]),MAX_POINTS=16,MAX_NAME=24,MAX_PLAYS=50,QB_BEHIND=.9;export function isCustomId(t){return typeof t=="string"&&t.startsWith(PLAY_ID_PREFIX)&&t.length>PLAY_ID_PREFIX.length}export function newPlayId(t=Date.now()){return`${PLAY_ID_PREFIX}${Math.floor(t).toString(36)}`}export function resolvePlay(t){if(t&&typeof t=="object"){const e=typeof t.base=="string"&&t.base?t.base:"",r=typeof t.id=="string"&&t.id?t.id:e,o=t.routes&&typeof t.routes=="object"?t.routes:{};return{id:r,base:e,routes:o}}const n=typeof t=="string"?t:"";return{id:n,base:n,routes:null}}export function toSim(t,n){return{x:t[0]*n.width,y:t[1]*n.height}}export function toNormalized(t,n,e){return[t/e.width,n/e.height]}const x=t=>t<0?0:t>1?1:t;export function normalizeLine(t){if(!Array.isArray(t)||t.length===0)return null;const n=[];for(const e of t.slice(0,MAX_POINTS)){if(!Array.isArray(e)||e.length<2)return null;const r=Number(e[0]),o=Number(e[1]);if(!Number.isFinite(r)||!Number.isFinite(o))return null;n.push([x(r),x(o)])}return n}export function normalizeRecord(t,n=[],e="pass4"){if(!t||typeof t!="object"||!isCustomId(t.id))return null;const r=typeof t.name=="string"?t.name.trim().slice(0,MAX_NAME):"";if(!r)return null;let o=typeof t.base=="string"?t.base:"";if(n.includes(o)||(o=n.includes(e)?e:n[0]||""),!o)return null;const i={};if(t.routes&&typeof t.routes=="object")for(const s of PATH_PLAYERS){const f=normalizeLine(t.routes[s]);f&&(i[s]=f)}const u=typeof t.created=="string"?t.created:"";return{id:t.id,name:r,base:o,routes:i,created:u,hidden:t.hidden===!0}}export function pathState(t){return{points:t.map(n=>({x:n.x,y:n.y})),seg:0,done:!1}}function h(t,n,e,r){const o=n.x-t.x,i=n.y-t.y,u=o*o+i*i;return u>0?((e-t.x)*o+(r-t.y)*i)/u:1}function m(t){if(t.lengths)return;const n=t.points;t.lengths=[],t.cum=[0];for(let e=0;e<n.length-1;e+=1){const r=Math.hypot(n[e+1].x-n[e].x,n[e+1].y-n[e].y);t.lengths.push(r),t.cum.push(t.cum[e]+r)}t.total=t.cum[t.cum.length-1]}function d(t,n){const e=t.points;if(n<=0)return e[0];if(n>=t.total)return e[e.length-1];let r=0;for(;r<t.lengths.length-1&&t.cum[r+1]<=n;)r+=1;const o=t.lengths[r],i=o>0?(n-t.cum[r])/o:1;return{x:e[r].x+(e[r+1].x-e[r].x)*i,y:e[r].y+(e[r+1].y-e[r].y)*i}}export function followPath(t,n,e,r=0){const o=t&&t.points;if(!o||o.length===0)return null;const i=o[o.length-1],u=Math.hypot(i.x-n,i.y-e);if(o.length===1)return{x:i.x,y:i.y,toEnd:u,end:!0};m(t);let s=t.seg||0;for(;s<o.length-2;){const c=o[s+1];if(!((c.x-o[s].x)*(o[s+2].x-c.x)+(c.y-o[s].y)*(o[s+2].y-c.y)<0&&r>0&&Math.hypot(c.x-n,c.y-e)<=r)&&h(o[s],c,n,e)<1)break;s+=1}t.seg=s;const f=Math.max(0,Math.min(1,h(o[s],o[s+1],n,e))),l=t.cum[s]+f*t.lengths[s]+Math.max(0,r),g=d(t,l),y=l>=t.total;return{x:g.x,y:g.y,toEnd:u,end:y}}export function approachSpeed(t,n,e,r){const o=n-t;if(o===0)return t;const u=Math.abs(n)>Math.abs(t)&&(t===0||Math.sign(n)===Math.sign(t))?e:r;return Math.abs(o)<=u?n:t+Math.sign(o)*u}
